//! Token budget for the optional rewind branch summary.
//!
//! When a rewind throws away part of the conversation, the agent can summarise
//! the discarded branch and append the report to the kept branch. The summary
//! is generated by an auxiliary completion, so it needs its own small token
//! allowance rather than borrowing the session model's context budget.
//!
//! The default below is horon's own choice: it is not the value of any other
//! agent's default, and it is deliberately small because the report is a few
//! short sections (what was tried, what failed, what was learned), not a
//! transcript copy.

/// Default token allowance for a rewind branch summary.
///
/// Chosen by horon as a balance between a report detailed enough to be useful
/// after resuming a branch and a cost small enough to keep the auxiliary call
/// cheap. Overridable with `[compaction] rewind_summary_tokens`.
pub const DEFAULT_REWIND_SUMMARY_TOKENS: usize = 1500;

/// Smallest allowance the auxiliary completion path accepts.
pub const MIN_REWIND_SUMMARY_TOKENS: usize = 1;

/// Largest allowance the auxiliary completion path accepts.
///
/// Mirrors the provider request ceiling of the auxiliary completion path;
/// clamping here keeps a config typo from failing the summary request outright.
pub const MAX_REWIND_SUMMARY_TOKENS: usize = 4096;

/// Clamp a configured allowance into the range the auxiliary path accepts.
///
/// `0` (the value an unset `usize` deserialises to when a config omits the key
/// while forcing `#[serde(default)]`) means "use the default", matching how
/// other `0 = no override` compaction settings behave.
pub fn clamp_rewind_summary_tokens(tokens: usize) -> usize {
    if tokens == 0 {
        return DEFAULT_REWIND_SUMMARY_TOKENS;
    }
    tokens.clamp(MIN_REWIND_SUMMARY_TOKENS, MAX_REWIND_SUMMARY_TOKENS)
}
